mapper.update:
UPDATE t_webhook_signing_secret SET status = 'RETIRED', signing_slot = NULL, valid_until = #{validUntil},
version = version + 1, update_time = #{now}
WHERE signing_secret_id = #{item.signingSecretId} AND version = #{item.version} AND status = 'ACTIVE'

UPDATE t_webhook_signing_secret SET valid_until = #{now}, version = version + 1, update_time = #{now}
WHERE signing_secret_id = #{item.signingSecretId} AND version = #{item.version} AND status = 'RETIRED'
AND valid_until > #{now}
